user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses an intended future course of action — a sequence of steps or a single upcoming operation the agent intends to perform — rather than reporting already completed work.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing an intended future action or an ordered set of intended steps."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least one action or outcome the agent intends to produce in the future.",
      "The intended action is stated as something to be done, not as something already done."
    ],
    "exclusion_conditions": [
      "The reasoning only reports completed actions or observed results.",
      "The reasoning only explains background knowledge without committing to a future action."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning states a conclusion or interpretation that is supported by identifiable content of the observation, so that the observation functions as evidence for that conclusion.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning expressing the conclusion or interpretation drawn from the evidence."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation whose content supplies the supporting evidence for that conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion, interpretation, or generalized finding, not merely a restatement of the raw result.",
      "Specific content of the observation is identifiable as the basis for that conclusion."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or paraphrases the observation without drawing a conclusion.",
      "The observation is unrelated to the stated conclusion or supplies no identifiable support.",
      "The conclusion is derived solely from prior knowledge or from task instructions rather than from the observation."
    ]
  },
  {
    "name": "RESOLVES_UNDERSPECIFIED_REQUIREMENT",
    "definition": "The reasoning explicitly identifies an ambiguity, gap, or unspecified aspect of the given requirements and adopts a concrete interpretation or design choice to proceed, without the resolution being settled by observed evidence.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text recognizing the underspecified requirement and committing to a concrete interpretation or default."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least one requirement whose meaning, naming, or behavior is not determined by the task statement.",
      "The reasoning selects or endorses a specific interpretation, default value, or behavior to resolve that gap."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates the requirement without noting any ambiguity.",
      "The ambiguity is settled by an observed experimental result rather than by a chosen interpretation.",
      "The reasoning defers the choice without adopting any concrete resolution."
    ]
  },
  {
    "name": "TESTS_ASSUMPTION_WITH_PROBE",
    "definition": "A targeted action is performed to settle an uncertainty or assumption identified in reasoning, and the resulting observation provides interpretable evidence bearing on that uncertainty.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action carried out as the targeted empirical test."
      },
      {
        "name": "assumption_reasoning",
        "type": "reasoning",
        "description": "The reasoning that states the uncertainty or assumption being tested."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting the outcome that informs the tested uncertainty."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific uncertainty or competing expectation that cannot be settled by reasoning alone.",
      "The action is directed at producing the information needed to settle that uncertainty.",
      "The resulting observation contains information that distinguishes between the competing possibilities."
    ],
    "exclusion_conditions": [
      "No identifiable assumption or uncertainty motivates the action.",
      "The action is unrelated to the stated uncertainty or serves only to make progress on an unrelated step.",
      "The observation does not address the tested uncertainty."
    ]
  },
  {
    "name": "REPORTS_EXECUTION_ERROR",
    "definition": "The observation records that an attempted operation did not succeed, conveying an error status, failure message, or missing-resource fault rather than a valid result of the requested operation.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation conveying non-success of the attempted operation."
      }
    ],
    "assertion_conditions": [
      "The observation carries an explicit error indication such as an error flag, failure message, or reported fault.",
      "The error indication concerns the operation that was attempted, so the attempt is not confirmed as successful."
    ],
    "exclusion_conditions": [
      "The observation reports a successful completion or a normal result value.",
      "The observation reports a negative fact about the domain state while the operation itself succeeded."
    ]
  },
  {
    "name": "REMEDIATES_FAILURE_WITH_CORRECTED_RETRY",
    "definition": "After an error is reported for an earlier attempt, reasoning diagnoses the cause of that error and a subsequent action repeats the attempt with the identified cause addressed, rather than repeating the same attempt unchanged.",
    "parameters": [
      {
        "name": "corrective_action",
        "type": "action",
        "description": "The repeated attempt whose invocation differs so as to address the diagnosed cause."
      },
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the error of the earlier attempt."
      },
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The reasoning that attributes the failure to a specific cause and indicates how to correct it."
      }
    ],
    "assertion_conditions": [
      "The observation reports an unsuccessful attempt of the same kind as the corrective action.",
      "The reasoning names or clearly implies the cause of that failure.",
      "The corrective action is a repetition of the attempt in which the identified cause is removed or compensated for."
    ],
    "exclusion_conditions": [
      "The retry repeats the failed attempt without any change addressing the cause.",
      "No failure is reported for the earlier attempt.",
      "The reasoning only acknowledges the error without identifying a cause that the corrective action addresses."
    ]
  },
  {
    "name": "WORKS_AROUND_UNAVAILABLE_TOOL",
    "definition": "An observation reports that a required tool or command is unavailable in the environment, reasoning selects an alternative means to obtain the same information or effect, and a subsequent action performs that alternative.",
    "parameters": [
      {
        "name": "alternative_action",
        "type": "action",
        "description": "The action employing the substitute means to reach the intended information or effect."
      },
      {
        "name": "availability_observation",
        "type": "observation",
        "description": "The observation indicating that the originally used tool or command is missing or unusable."
      },
      {
        "name": "workaround_reasoning",
        "type": "reasoning",
        "description": "The reasoning that acknowledges the unavailability and proposes the alternative means."
      }
    ],
    "assertion_conditions": [
      "The observation establishes that the original tool or command cannot be used in this environment.",
      "The reasoning explicitly proposes a different means of achieving the same informational or functional goal.",
      "The alternative action implements that proposed means."
    ],
    "exclusion_conditions": [
      "The observation shows the tool worked and returned a usable result.",
      "The action repeats the unavailable tool or otherwise does not follow the proposed alternative.",
      "The reasoning merely notes the missing tool without proposing or adopting a substitute."
    ]
  },
  {
    "name": "MATERIALIZES_DESIGNED_ARTIFACT",
    "definition": "The reasoning contains a concrete specification of an artifact to be produced (such as its content, structure, or interface), and an action creates that artifact with content corresponding to the specification.",
    "parameters": [
      {
        "name": "creation_action",
        "type": "action",
        "description": "The action that produces or writes the artifact."
      },
      {
        "name": "design_reasoning",
        "type": "reasoning",
        "description": "The reasoning containing the concrete specification of the artifact's content or structure."
      }
    ],
    "assertion_conditions": [
      "The reasoning specifies concrete artifact content or structure rather than only a high-level goal.",
      "The action produces an artifact whose content corresponds identifiably to that specification."
    ],
    "exclusion_conditions": [
      "The reasoning only states an intention to create something without specifying its content or structure.",
      "The produced artifact's content does not correspond to the specification in the reasoning.",
      "The action produces the artifact without any preceding specification of its content."
    ]
  }
]

Existing registry:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses at least one intended future action or sequence of actions to be taken in service of the task.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing an intended future action or plan."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one operation or sequence of operations that the agent intends to perform later.",
      "The intended action is presented as something to be done, not merely as a completed observation or factual statement."
    ],
    "exclusion_conditions": [
      "The reasoning only reports actions that have already been completed.",
      "The reasoning states a fact or diagnosis without expressing any intended future action.",
      "The reasoning only restates the task requirements without committing to any operation the agent will itself carry out."
    ]
  },
  {
    "name": "ACTION_IMPLEMENTS_PLANNED_STEP",
    "definition": "A recorded action carries out an operation that a reasoning node explicitly proposed as a future step, with matching task purpose rather than merely topical or temporal adjacency.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The recorded tool invocation that performs the step."
      },
      {
        "name": "plan_reasoning",
        "type": "reasoning",
        "description": "The reasoning node that proposes the future operation."
      }
    ],
    "assertion_conditions": [
      "The plan_reasoning expresses an intended future operation or set of operations.",
      "The action performs an operation consistent with the purpose and target of the proposed step."
    ],
    "exclusion_conditions": [
      "The reasoning only describes past or completed actions.",
      "The action is unrelated to the proposed step or serves a different purpose.",
      "The connection is based only on temporal adjacency without matching intent."
    ]
  },
  {
    "name": "DIAGNOSES_OBSERVED_ARTIFACT_DEFECT",
