    "parameters": [
      {
        "name": "expectation_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the expected behavior, output, content, result, state, or constraint."
      },
      {
        "name": "check_action",
        "type": "action",
        "description": "The action executing an operation, inspection, or comparison capable of producing or observing the expected outcome."
